import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

export default function Dashboard() {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [user, setUser] = useState(null);
    const [stats, setStats] = useState({});

    useEffect(() => {
        const token = localStorage.getItem("jwt_token");
        if (!token) return navigate("/login");

        (async () => {
            try {
                const res = await fetch("/api/dashboard/", {
                    headers: { Authorization: `Bearer ${token}` }
                });

                if (res.status === 401 || res.status === 403) {
                    localStorage.removeItem("jwt_token");
                    return navigate("/login");
                }

                const data = await res.json();
                if (!res.ok) throw new Error(data.message || "Failed to load dashboard");

                setUser(data.user);
                setStats(data.stats);
            } catch (err) {
                setError(err.message);
            } finally {
                setLoading(false);
            }
        })();
    }, [navigate]);

    if (loading) return <Center>Loading dashboard…</Center>;
    if (error) return <Alert>{error}</Alert>;

    const isAdmin = user?.primary_role === "admin";

    const Card = ({ bg = "bg-light", title, value = 0, desc, link }) => (
        <div className="col-md-4 mb-3">
            <div className={`card text-white dashboard-card ${bg}`}>
                <div className="card-body text-center">
                    <h5>{title}</h5>
                    <h2>{value}</h2>
                    <p>{desc}</p>
                    {link && <a href={link} className="btn btn-light btn-sm mt-2">Open</a>}
                </div>
            </div>
        </div>
    );

    return (
        <div className="container mt-5 pt-4">
            <div className="text-center">
                <h2>Welcome, {user.fullname}</h2>
                <p className="text-muted">{user.email}</p>
                <hr />
            </div>

            {/* User Stats */}
            <div className="row text-center mt-4">
                <Card bg="bg-success" title="📝 Active Consents" value={stats.active_consents} desc="Consents Granted" link="/myconsents" />
                <Card bg="bg-warning text-dark" title="📨 Grievances" value={stats.grievances_count} desc="Filed by You" link="/mygrievances" />
                <Card bg="bg-info" title="🔔 Notifications" value={stats.unread_notifications} desc="Unread Notifications" link="/notifications" />
            </div>

            {/* Admin Section */}
            {isAdmin ? (
                <AdminSection stats={stats} />
            ) : (
                <UserSection role={user.primary_role} />
            )}
        </div>
    );
}

function Center({ children }) {
    return <div className="container mt-5 text-center">{children}</div>;
}

function Alert({ children }) {
    return <div className="container mt-5"><div className="alert alert-danger text-center">{children}</div></div>;
}

function AdminSection({ stats }) {
    return (
        <>
            <div className="text-center mt-4">
                <h3 className="text-primary">Admin Dashboard</h3>
                <p>Manage users, companies, and consent data.</p>
            </div>

            <div className="row text-center mt-4">
                <AdminCard title="👥 Users" value={stats.total_users} link="/showallusers" color="primary" />
                <AdminCard title="📝 Consents" value={stats.total_consents} link="/showallconsents" color="success" />
                <AdminCard title="💬 Feedbacks" value={stats.total_feedbacks} link="/showallfeedbacks" color="warning" />
                <AdminCard title="⚖️ Grievances" value={stats.total_grievances} link="/admin/grievances" color="danger" />
            </div>
        </>
    );
}

function AdminCard({ title, value = 0, link, color }) {
    return (
        <div className="col-md-3 mb-3">
            <div className={`card bg-${color} text-white`}>
                <div className="card-body text-center">
                    <h5>{title}</h5>
                    <h2>{value}</h2>
                    <a href={link} className="btn btn-light btn-sm mt-2">Open</a>
                </div>
            </div>
        </div>
    );
}

function UserSection({ role }) {
    const roleName = role.charAt(0).toUpperCase() + role.slice(1);
    return (
        <div className="text-center mt-4">
            <h3 className="text-success">{roleName} Dashboard</h3>
            <p>Welcome to your personalized DPCMS dashboard.</p>

            <div className="d-flex flex-wrap justify-content-center gap-3 mt-4">
                <a href="/consent/status" className="btn btn-primary">Manage Consent</a>
                <a href="/myconsents" className="btn btn-success">My Consents</a>
                <a href="/mygrievances" className="btn btn-warning">My Grievances</a>
                <a href="/notifications" className="btn btn-info">My Notifications</a>
            </div>
        </div>
    );
}
